{
  "name": "opencode-gemini-dejavu",
  "version": "0.2.2",
  "description": "OpenCode plugin that mitigates Gemini 3.x repeated tool-call deja vu with request-local turn boundaries.",
  "license": "MIT",
  "author": "isac322 <bh322yoo@gmail.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/isac322/opencode-gemini-dejavu.git"
  },
  "homepage": "https://github.com/isac322/opencode-gemini-dejavu#readme",
  "bugs": {
    "url": "https://github.com/isac322/opencode-gemini-dejavu/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "gemini",
    "gemini-3",
    "google-gemini",
    "vertex-ai",
    "thought-signature",
    "agent",
    "tool-call-loop",
    "repeated-tool-calls"
  ],
  "type": "module",
  "main": "./dist/plugin.js",
  "types": "./dist/plugin.d.ts",
  "exports": {
    ".": {
      "types": "./dist/plugin.d.ts",
      "default": "./dist/plugin.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "sideEffects": false,
  "engines": {
    "node": ">=18.17"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsgo -p tsconfig.build.json",
    "typecheck": "tsgo --noEmit",
    "check": "biome check .",
    "test": "bun test-fixture.ts fixtures/minimal-loop && bun test-hook.ts fixtures/minimal-loop",
    "test:fixture": "bun test-fixture.ts",
    "test:hook": "bun test-hook.ts",
    "prepublishOnly": "bun run typecheck && bun run check && bun run test && bun run build"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.4.16",
    "@opencode-ai/plugin": "^1.15.12",
    "@types/bun": "^1.3.14",
    "@types/node": "^25.9.1",
    "@typescript/native-preview": "^7.0.0-dev.20260527.2"
  }
}
